/**
 * Check operand references to memory locations looking for Data
 */
public class AddressTableAnalyzer : AbstractAnalyzer {
	private static string DESCRIPTION = "Analyzes undefined data for address tables.";

	private static readonly string OPTION_NAME_MIN_TABLE_SIZE = "Minimum Table Size";
	private static readonly string OPTION_NAME_TABLE_ALIGNMENT = "Table Alignment";
	private static readonly string OPTION_NAME_PTR_ALIGNMENT = "Pointer Alignment";
	private static readonly string OPTION_NAME_AUTO_LABEL_TABLE = "Auto Label Table";
	private static readonly string OPTION_NAME_MIN_POINTER_ADDR = "Minimum Pointer Address";
	private static readonly string OPTION_NAME_MAX_POINTER_DIFF = "Maxmimum Pointer Distance";
	private static readonly string OPTION_NAME_RELOCATION_GUIDE = "Relocation Table Guide";
	private static readonly string OPTION_NAME_ALLOW_OFFCUT_REFERENCES = "Allow Offcut References";

	protected static readonly string OPTION_NAME_CREATE_BOOKMARKS = "Create Analysis Bookmarks";
	private static readonly string OPTION_DESCRIPTION_CREATE_BOOKMARKS =
		"If checked, an analysis bookmark will be created at each location where an address table is constructed.";
	private static readonly bool OPTION_DEFAULT_CREATE_BOOKMARKS_ENABLED = true;

	private static readonly string OPTION_DESCRIPTION_MIN_TABLE_SIZE =
		"The minimum number of consecutive addresses that constitute an address table";
	private static readonly string OPTION_DESCRIPTION_TABLE_ALIGNMENT =
